ns.Data.glyphs[40896] = { "Glyph of Frenzied Regeneration", "Символ неистового восстановления", "inv_glyph_majordruid", "While Frenzied Regeneration is active, healing effects on you are 20% more powerful.", "Увеличивает получаемое исцеление на 20%, пока вы находитесь под эффектом \"Неистового восстановления\" .", 54854 }
ns.Data.glyphs[40897] = { "Glyph of Maul", "Символ трепки", "inv_glyph_majordruid", "Your Maul ability now hits 1 additional target.", "Увеличивает количество целей, поражаемых способностью \"Трепка\", на 1.", 54858 }
ns.Data.glyphs[40901] = { "Glyph of Shred", "Символ полосования", "inv_glyph_majordruid", "Each time you Shred, the duration of your Rip on the target is extended 2 sec, up to a maximum of 6 sec.", "Увеличивает время действия способности \"Разорвать\" на цель на 2 сек. при каждом использовании способности \"Полоснуть\" вплоть до максимального значения в 6 сек.", 54859 }
ns.Data.glyphs[40902] = { "Glyph of Rip", "Символ разрывания", "inv_glyph_majordruid", "Increases the duration of your Rip ability by 4 sec.", "Увеличивает время действия способности \"Разорвать\" на 4 сек.", 54860 }
ns.Data.glyphs[40906] = { "Glyph of Swiftmend", "Символ быстрого восстановления", "inv_glyph_majordruid", "Your Swiftmend ability no longer consumes a Rejuvenation or Regrowth effect from the target.", "При применении заклинания \"Быстрое восстановление\" с цели не снимаются эффекты \"Омоложение\" и \"Восстановление\".", 54864 }
ns.Data.glyphs[40916] = { "Glyph of Starfire", "Символ звездного огня", "inv_glyph_majordruid", "Your Starfire ability increases the duration of your Moonfire effect on the target by 3 sec, up to a maximum of 9 additional seconds.", "Увеличивает время действия эффекта \"Лунный огонь\" на цели на 3 сек. при каждом использовании заклинания \"Звездный огонь\" вплоть до 9 сек. дополнительно.", 54871 }
ns.Data.glyphs[40919] = { "Glyph of Insect Swarm", "Символ роя насекомых", "inv_glyph_majordruid", "Increases the damage of your Insect Swarm ability by 30%, but it no longer affects your victim's chance to hit.", "Увеличивает урон от способности \"Рой насекомых\" на 30%, но эта способность более не влияет на шанс попадания противника по цели.", 54872 }
ns.Data.glyphs[40921] = { "Glyph of Starfall", "Символ звездопада", "inv_glyph_majordruid", "Reduces the cooldown of Starfall by 30 sec.", "Сокращает время восстановления заклинания \"Звездопад\" на 30 сек.", 54874 }
ns.Data.glyphs[40923] = { "Glyph of Moonfire", "Символ лунного огня", "inv_glyph_majordruid", "Increases the periodic damage of your Moonfire ability by 75%, but initial damage is decreased by 90%.", "Увеличивает периодический урон от заклинания \"Лунный огонь\" на 75%, уменьшая изначальный урон на 90%.", 54876 }
ns.Data.glyphs[41092] = { "Glyph of Judgement", "Символ правосудия", "inv_glyph_majorpaladin", "Your Judgements deal 10% more damage.", "Увеличивает урон, наносимый заклинанием \"Правосудие\", на 10%.", 55003 }
