ns.Data.glyphs[43546] = { "Glyph of Icy Touch", "Символ ледяного прикосновения", "inv_glyph_majordeathknight", "Your Frost Fever disease deals 20% additional damage.", "Увеличивает урон от вашей болезни \"Озноб\" на 20%.", 58718 }
ns.Data.glyphs[43547] = { "Glyph of Obliterate", "Символ уничтожения", "inv_glyph_majordeathknight", "Increases the damage of your Obliterate ability by 25%.", "Увеличивает урон от способности \"Уничтожение\" на 25%.", 58719 }
ns.Data.glyphs[43549] = { "Glyph of the Ghoul", "Символ вурдалака", "inv_glyph_majordeathknight", "Your Ghoul receives an additional 40% of your Strength and 40% of your Stamina.", "Сила вурдалака возрастает на 40% от вашей силы, а его выносливость – на 40% от вашей выносливости.", 58721 }
ns.Data.glyphs[43550] = { "Glyph of Rune Strike", "Символ рунического удара", "inv_glyph_majordeathknight", "Increases the critical strike chance of your Rune Strike by 10%.", "Увеличивает вероятность нанести критический урон способностью \"Рунический удар\" на 10%.", 58722 }
ns.Data.glyphs[43672] = { "Glyph of Pestilence", "Символ мора", "inv_glyph_minordeathknight", "Increases the radius of your Pestilence effect by 5 yards.", "Увеличивает радиус воздействия способности \"Мор\" на 5 м.", 59311 }
ns.Data.glyphs[43673] = { "Glyph of Raise Dead", "Символ воскрешения мертвых", "inv_glyph_minordeathknight", "Your Raise Dead spell no longer requires a reagent.", "Заклинание \"Воскрешение мертвых\" не требует реагентов.", 59313 }
ns.Data.glyphs[43674] = { "Glyph of Dash", "Символ порыва", "inv_glyph_minordruid", "Reduces the cooldown of your Dash ability by 20%.", "Сокращает время восстановления способности \"Порыв\" на 20%.", 59218 }
ns.Data.glyphs[43725] = { "Glyph of Ghost Wolf", "Символ призрачного волка", "inv_glyph_minorshaman", "Your Ghost Wolf form regenerates an additional 1% of your maximum health every 5 sec.", "В облике призрачного волка вы дополнительно восстанавливаете 1% от вашего максимального здоровья каждые 5 сек.", 59287 }
ns.Data.glyphs[43827] = { "Glyph of Death Strike", "Символ удара смерти", "inv_glyph_majordeathknight", "Increases your Death Strike's damage by 1% for every 1 runic power you currently have (up to a maximum of 25%). The runic power is not consumed by this effect.", "Увеличивает урон от способности \"Удар смерти\" на 1% за каждые 1 ед. накопленной силы рун (максимум на 25%). Сила рун при этом не расходуется.", 59337 }
ns.Data.glyphs[43869] = { "Glyph of Seal of Vengeance", "Символ печати отмщения", "inv_glyph_majorpaladin", "Your Seal of Vengeance or Seal of Corruption also grants 10 expertise while active.", "Во время действия заклинаний \"Печать отмщения\" и \"Печать порчи\" ваше мастерство повышается на 10.", 59429 }
ns.Data.glyphs[44684] = { "Glyph of Frostfire", "Символ ледяного огня", "inv_glyph_majormage", "Increases the initial damage dealt by Frostfire Bolt by 2% and its critical strike chance by 2%.", "Увеличивает начальный урон от заклинания \"Стрела ледяного огня\" на 2% и повышает вероятность критического удара этого заклинания на 2%.", 61206 }
ns.Data.glyphs[44920] = { "Glyph of Blast Wave", "Символ взрывной волны", "inv_glyph_minormage", "The mana cost of your Blast Wave spell is reduced by 15%, but it no longer knocks enemies back.", "Расход маны на заклинание \"Взрывная волна\" уменьшен на 15%, но теперь оно не отбрасывает противников.", 62127 }
ns.Data.glyphs[44922] = { "Glyph of Typhoon", "Символ тайфуна", "inv_glyph_minordruid", "Reduces the cost of your Typhoon spell by 8% and increases its radius by 10 yards, but it no longer knocks enemies back.", "Снижает затраты маны на заклинание \"Тайфун\" на 8%, увеличивает радиус его действия на 10 м, но заклинание больше не отбрасывает противников назад.", 62134 }
ns.Data.glyphs[44923] = { "Glyph of Thunderstorm", "Символ грома и молнии", "inv_glyph_minorshaman", "Increases the mana you receive from your Thunderstorm spell by 2%, but it no longer knocks enemies back.", "Увеличивает количество маны, получаемой при применении заклинания \"Гром и молния\", на 2%. Заклинание больше не отбрасывает противников назад.", 62133 }
ns.Data.glyphs[44928] = { "Glyph of Focus", "Символ фокусирования", "inv_glyph_majordruid", "Increases the damage done by Starfall by 10%, but decreases its radius by 50%.", "Увеличивает урон от заклинания \"Звездопад\" на 10%, но уменьшает радиус его действия на 50%.", 62161 }
ns.Data.glyphs[44955] = { "Glyph of Arcane Blast", "Символ чародейской вспышки", "inv_glyph_majormage", "Increases the damage from your Arcane Blast buff by 3%.", "Увеличивает урон от эффекта \"Чародейская вспышка\" на 3%.", 62353 }
ns.Data.glyphs[45602] = { "Glyph of Wild Growth", "Символ буйного роста", "inv_glyph_majordruid", "Wild Growth can affect 1 additional target.", "Заклинание \"Буйный рост\" воздействует дополнительно на 1 цель.", 63715 }
ns.Data.glyphs[45603] = { "Glyph of Nourish", "Символ покровительства природы", "inv_glyph_majordruid", "Your Nourish heals an additional 6% for each of your heal over time effects present on the target.", "Заклинание \"Покровительство природы\" теперь восстанавливает на 6% больше здоровья за каждый наложенный на цель эффект постепенного лечения.", 63717 }
ns.Data.glyphs[45604] = { "Glyph of Savage Roar", "Символ дикого рева", "inv_glyph_majordruid", "Your Savage Roar ability grants an additional 3% bonus damage done.", "Способность \"Дикий рев\" увеличивает бонус урона дополнительно на 3%.", 63718 }
ns.Data.glyphs[45732] = { "Glyph of Kill Shot", "Символ убийственного выстрела", "inv_glyph_majorhunter", "Reduces the cooldown of Kill Shot by 6 sec.", "Сокращает время восстановления способности \"Убийственный выстрел\" на 6 сек.", 63855 }
ns.Data.glyphs[45733] = { "Glyph of Explosive Trap", "Символ взрывной ловушки", "inv_glyph_majorhunter", "The periodic damage from your Explosive Trap can now be critical strikes.", "Периодический урон, наносимый способностью \"Взрывная ловушка\", теперь может быть критическим.", 63856 }
ns.Data.glyphs[45737] = { "Glyph of Living Bomb", "Символ живой бомбы", "inv_glyph_majormage", "The periodic damage from your Living Bomb can now be critical strikes.", "Периодический урон от заклинания \"Живая бомба\" теперь может быть критическим.", 63860 }
ns.Data.glyphs[45741] = { "Glyph of Beacon of Light", "Символ частицы Света", "inv_glyph_majorpaladin", "Increases the duration of Beacon of Light by 30 sec.", "Увеличивает время действия заклинания \"Частица Света\" на 30 сек.", 63865 }
ns.Data.glyphs[45745] = { "Glyph of Divine Plea", "Символ святой клятвы", "inv_glyph_majorpaladin", "While Divine Plea is active, you take 3% reduced damage from all sources.", "Когда паладин находится под действием заклинания \"Святая клятва\", весь получаемый им урон уменьшается на 3%.", 63869 }
ns.Data.glyphs[45753] = { "Glyph of Dispersion", "Символ слияния с Тьмой", "inv_glyph_majorpriest", "Reduces the cooldown on Dispersion by 45 sec.", "Сокращает время восстановления заклинания \"Слияние с Тьмой\" на 45 сек.", 63872 }
ns.Data.glyphs[45756] = { "Glyph of Penance", "Символ исповеди", "inv_glyph_majorpriest", "Reduces the cooldown of Penance by 2 sec.", "Сокращает время восстановления заклинания \"Исповедь\" на 2 сек.", 63874 }
ns.Data.glyphs[45761] = { "Glyph of Hunger for Blood", "Символ жажды убийства", "inv_glyph_majorrogue", "Increases the bonus damage from Hunger For Blood by 3%.", "Увеличивает дополнительный урон от способности \"Жажда убийства\" на 3%.", 63878 }
ns.Data.glyphs[45762] = { "Glyph of Killing Spree", "Символ череды убийств", "inv_glyph_majorrogue", "Reduces the cooldown on Killing Spree by 45 sec.", "Сокращает время восстановления способности \"Череда убийств\" на 45 сек.", 63879 }
ns.Data.glyphs[45767] = { "Glyph of Tricks of the Trade", "Символ маленьких хитростей", "inv_glyph_majorrogue", "The bonus damage and threat redirection granted by your Tricks of the Trade ability lasts an additional 4 sec.", "Дополнительный урон и снижение угрозы, обеспечиваемые способностью \"Маленькие хитрости\", действуют на 4 сек. дольше.", 63898 }
ns.Data.glyphs[45768] = { "Glyph of Mutilate", "Символ расправы", "inv_glyph_majorrogue", "Reduces the cost of Mutilate by 5 energy.", "Снижает затраты энергии на способность \"Расправа\" на 5 ед.", 63899 }
ns.Data.glyphs[45771] = { "Glyph of Feral Spirit", "Символ духа дикого волка", "inv_glyph_majorshaman", "Your spirit wolves gain an additional 30% of your attack power.", "Увеличивает силу атаки ваших призрачных волков на 30% от вашей силы атаки.", 63903 }
ns.Data.glyphs[45775] = { "Glyph of Earth Shield", "Символ щита земли", "inv_glyph_majorshaman", "Increases the amount healed by your Earth Shield by 20%.", "Увеличивает количество здоровья, восстанавливаемого заклинанием \"Щит земли\", на 20%.", 63925 }
ns.Data.glyphs[45776] = { "Glyph of Totem of Wrath", "Символ тотема гнева", "inv_glyph_majorshaman", "When you cast Totem of Wrath, you gain 30% of the totem's bonus spell power for 5 min.", "При установке тотема гнева сила заклинаний шамана возрастает на 30% от бонуса силы заклинаний, обеспечиваемого тотемом. Время действия эффекта – 5 min.", 63926 }
ns.Data.glyphs[45779] = { "Glyph of Haunt", "Символ блуждающего духа", "inv_glyph_majorwarlock", "The bonus damage granted by your Haunt spell is increased by an additional 3%.", "Увеличивает дополнительный урон от способности \"Блуждающий дух\" еще на 3%.", 63930 }
ns.Data.glyphs[45785] = { "Glyph of Life Tap", "Символ жизнеотвода", "inv_glyph_majorwarlock", "When you use Life Tap or Dark Pact, you gain 20% of your Spirit as spell power for 40 sec.", "После применения способностей \"Жизнеотвод\" или \"Темный союз\" ваша сила заклинаний возрастает на 20% от показателя вашего духа на 40 sec.", 63941 }
ns.Data.glyphs[45793] = { "Glyph of Vigilance", "Символ бдительности", "inv_glyph_majorwarrior", "Your Vigilance ability transfers an additional 5% of your target's threat to you.", "Способность \"Бдительность\" перенаправляет на воина дополнительно 5% от угрозы, создаваемой выбранным союзником.", 63949 }
ns.Data.glyphs[45799] = { "Glyph of Dancing Rune Weapon", "Символ танцующего рунического оружия", "inv_glyph_majordeathknight", "Increases the duration of Dancing Rune Weapon by 5 sec.", "Увеличивает время действия способности \"Танцующее руническое оружие\" на 5 сек.", 63953 }
ns.Data.glyphs[45804] = { "Glyph of Dark Death", "Символ черной смерти", "inv_glyph_majordeathknight", "Increases the damage or healing done by Death Coil by 15%.", "Увеличивает урон и эффективность исцеления вашего заклинания \"Лик смерти\" на 15%.", 63958 }
ns.Data.glyphs[45805] = { "Glyph of Disease", "Символ болезни", "inv_glyph_majordeathknight", "Your Pestilence ability now refreshes disease durations and secondary effects of diseases on your primary target back to their maximum duration.", "При использовании способности \"Мор\" время действия болезней и их вторичных эффектов на цели обновляется.", 63959 }
ns.Data.glyphs[46372] = { "Glyph of Survival Instincts", "Символ инстинкта выживания", "inv_glyph_majordruid", "Your Survival Instincts ability grants an additional 15% of your maximum health.", "Способность \"Инстинкты выживания\" повышает ваш максимальный запас здоровья дополнительно на 15%.", 65244 }
ns.Data.glyphs[49084] = { "Glyph of Command", "Символ властности", "inv_glyph_minorwarrior", "Increases the duration of your Commanding Shout ability by 2 min.", "Увеличивает время действия способности \"Командирский крик\" на 2 мин.", 68163 }
ns.Data.glyphs[50045] = { "Glyph of Eternal Water", "Символ извечной воды", "inv_glyph_majormage", "Your Summon Water Elemental now lasts indefinitely, but your Water Elemental can no longer cast Freeze.", "Время жизни призванного вами элементаля воды теперь не ограничено, но при этом он не может применять способность \"Холод\".", 70938 }
ns.Data.glyphs[50077] = { "Glyph of Quick Decay", "Символ быстрого разложения", "inv_glyph_majorwarlock", "Your haste now reduces the time between periodic damage ticks of your Corruption spell.", "Ваш рейтинг скорости теперь влияет на длину тактов заклинания \"Порча\".", 70948 }
ns.Data.glyphs[206953] = { "Glyph of Shattering Throw", "Символ сокрушительного броска", "inv_glyph_minorwarrior", "Your Shattering Throw is now instant and can be used in any stance, but it no longer removes invulnerabilities and cannot be used on players or player-controlled targets.", "\"Сокрушительный бросок\" теперь срабатывает мгновенно и действует в любой стойке, но больше не снимает эффекты неуязвимости и не действует на игроков или контролируемые ими цели.", 414813 }
